sending_cron = env.ref('booking_channex.ir_cron_data_channex_sender')
payloads = {
    'restrictions': [],
    'availability': [],
}

datas_to_send = env['x_channex_ari_update_lines'].search([])
for line in datas_to_send:
    payloads.setdefault(line.x_operation, []).append(line.x_payload)

for endpoint in ('restrictions', 'availability'):
    if payloads[endpoint]:
        try:
            env.ref('booking_channex.requests_to_channex').with_context(method='POST', endpoint=endpoint, payload={'values': payloads[endpoint]}).run()
        except Exception as e:
            env.ref('booking_channex.util_log_message').with_context(func='POST', path=endpoint, message=f"Auto Ari sync: Failed to send {endpoint} data; error is :\n{str(e)}").run()

model.env['ir.cron']._commit_progress(processed=1, remaining=0, deactivate=True)
datas_to_send.unlink()

property_mapping = env["x_channex_mapping"].search([
    ("x_model_type", "=", "property"),
    ("x_local_id", "=", record.company_id.id or env.company.id),
    ("x_remote_id", "!=", False),
], limit=1)
room_mapping = env["x_channex_mapping"].search([
    ("x_model_type", "=", "room_type"),
    ("x_local_id", "=", record.id),
    ("x_remote_id", "!=", False),
], limit=1)

if property_mapping and room_mapping:
    rate_plans = env["x_rate_plan"].search([('x_variant_id', '=', record.id)])
    today = datetime.datetime.today().date()
    date_list = [
        today + datetime.timedelta(days=i)
        for i in range(501)
    ]
    payload_values = env.ref('booking_channex.prepare_rate_payload').with_context(active_ids=rate_plans, property_remote_id=property_mapping.x_remote_id, date_list=date_list).run()
    # payload_values is list of dict with property_id, rate_plan_id, date_from, date_to, rate

    env['x_channex_ari_update_lines'].create([
        {
            'x_operation': 'restrictions',
            'x_payload': payload,
        }
        for payload in payload_values
    ])
    sending_cron = env.ref('booking_channex.ir_cron_data_channex_sender')
    if not sending_cron.active:
        sending_cron.write({'nextcall': datetime.datetime.now() + datetime.timedelta(minutes=1), 'active': True})

property_id = record.company_id.id or env.company.id
property_mapping = env["x_channex_mapping"].search([("x_model_type", "=", "property"),("x_local_id", "=", property_id),], limit=1)

if property_mapping.x_remote_id:
    room_domain = [("x_is_a_room_offer", "!=", False),('company_id', 'in', (False, property_id)),]

    if record.applied_on == "1_product":
        if record.product_id:
            room_domain.append(("id", "=", record.product_id.id))
        elif record.product_tmpl_id:
            room_domain.append(("product_tmpl_id", "=", record.product_tmpl_id.id))

    elif record.applied_on == "2_product_category":
        room_domain.append(("categ_id", "=", record.categ_id.id))

    property_rooms = env["product.product"].search(room_domain)

    if property_rooms:
        rate_plans = env["x_rate_plan"].search([('x_pricelist_id', '=', record.pricelist_id.id),('x_variant_id', 'in', property_rooms.ids)])
        if rate_plans:
            today = datetime.datetime.today()
            start_date = (
                record.date_start
                if record.date_start and record.date_start >= today
                else today
            )
            if not record.date_end:
                end_date = today + datetime.timedelta(days=501)
            elif record.date_end < today:
                end_date = False
            else:
                end_date = record.date_end
            if end_date:
                date_list = [
                    start_date + datetime.timedelta(days=i)
                    for i in range((end_date - start_date).days + 1)
                ]
                payload_values = env.ref('booking_channex.prepare_rate_payload').with_context(active_ids=rate_plans.ids, active_id=rate_plans.ids[0], active_model='x_rate_plan', property_remote_id=property_mapping.x_remote_id, date_list=date_list).run()

                if payload_values:
                    env['x_channex_ari_update_lines'].create([
                        {
                            'x_operation': 'restrictions',
                            'x_payload': payload,
                        }
                        for payload in payload_values
                    ])
                    sending_cron = env.ref('booking_channex.ir_cron_data_channex_sender')
                    if not sending_cron.active:
                        sending_cron.write({'nextcall': datetime.datetime.now() + datetime.timedelta(minutes=1), 'active': True})

room_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[('x_model_type', '=', 'room_type'),('x_local_id', 'in', record.x_stay_offer_id.product_variant_ids.ids)], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
property_mapping = env["x_channex_mapping"].search([
    ("x_model_type", "=", "property"),
    ("x_local_id", "=", record.x_stay_offer_id.company_id.id or env.company.id),
    ("x_remote_id", "!=", False),
], limit=1)
ota_buffer = record.x_stay_offer_id.x_ota_buffer
if property_mapping:
    for room in record.x_stay_offer_id.product_variant_ids:
        if room_remote_id := room_mappings_dict.get(room.id):
            env['x_channex_ari_update_lines'].create({
                'x_operation': 'availability',
                'x_payload': {
                    'property_id': property_mapping.x_remote_id,
                    'room_type_id': room_remote_id,
                    'date_from': record.x_date.strftime('%Y-%m-%d'),
                    'date_to': record.x_date.strftime('%Y-%m-%d'),
                    'availability': min(0, record.x_available - ota_buffer),
                },
            })
            sending_cron = env.ref('booking_channex.ir_cron_data_channex_sender')
            if not sending_cron.active:
                sending_cron.write({'nextcall': datetime.datetime.now() + datetime.timedelta(minutes=1), 'active': True})

if env['ir.config_parameter'].get_bool('booking_channex.synced_with_channex'):
    for group in records:
        group_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="group", local_id=group.id).run()
        if not group_mapping.x_remote_id:
            try:
                data = env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint='groups', payload={"group": {"title": group.x_name or ""}}).run()
                remote_id = data.json.get('data', {}).get('attributes', {}).get('id')
                if not remote_id:
                    raise UserError("Invalid response from Channex for the creation of a group corresponding to group with id %s" % str(property.id))
                group_mapping.write({'x_remote_id': remote_id})
            except Exception as e:
                sync_type = env.context.get('sync_type', 'Live')
                env.ref('booking_channex.util_log_message').with_context(func='POST', path='groups', message=f"{sync_type} sync: Failed to send group with ID {group.id}; error is :\n{str(e)}").run()

mappings = records.env['x_channex_mapping'].search([('x_model_type', '=', 'group'), ('x_local_id', 'in', records.ids), ('x_remote_id', '!=', False)])
if mappings and any(records.mapped('x_company_ids')): raise UserError("It is not possible to delete a channex group that contains companies. Please remove the companies through their page first.")
for mapping in mappings:
    env.ref('booking_channex.requests_to_channex').with_context(
        method="DELETE", endpoint="groups/%s" % mapping.x_remote_id
    ).run()
mappings.unlink()

mappings = records.env['x_channex_mapping'].search([('x_model_type', '=', 'group'), ('x_local_id', 'in', records.ids), ('x_remote_id', '!=', False)])
for mapping in mappings:
    try:
        env.ref('booking_channex.requests_to_channex').with_context(
            method="PUT", endpoint="groups/%s" % mapping.x_remote_id, payload={"group": {"title": env['x_channex_group'].browse(mapping.x_local_id).x_name or ""}}
        ).run()
    except Exception as e:
        sync_type = env.context.get('sync_type', 'Live')
        env.ref('booking_channex.util_log_message').with_context(func='PUT', path='groups', message=f"{sync_type} sync: Failed to update group with ID {mapping.x_local_id}; error is :\n{str(e)}").run()

# Validate that each Channex group is assigned to a single company before creating properties.
if records.filtered(lambda p: len(p.x_channex_group_id.x_company_ids) > 1):
    raise UserError("Only one company can be assigned to Channex group.")
if env['ir.config_parameter'].get_bool('booking_channex.synced_with_channex'):
    for property in records:
        property_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="property", local_id=property.id).run()
        group_mapping = records.env['x_channex_mapping'].search([('x_model_type', '=', 'group'), ('x_local_id', '=', property.x_channex_group_id.id), ('x_remote_id', '!=', False)], limit=1)
        if not property_mapping.x_remote_id and group_mapping:
            try:
                data = env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint="properties", payload={
                    "property": {
                        "title": property.name,
                        "currency": property.currency_id.name,
                        "email": property.email or '',
                        "phone": property.phone or '',
                        "group_id": group_mapping.x_remote_id,
                        "property_type": "hotel",  # TODO: Should be adapted based on the industry we use
                        "zip_code": property.zip or '',
                        "country": property.country_id.code or '',
                        "state": property.state_id.name or '',
                        "city": property.city or '',
                        "address": property.street or '',
                        "timezone": property.tz or '',
                        "website": property.website or '',
                    }
                }).run()
                remote_id = data.json.get('data', {}).get('attributes', {}).get('id')
                if not remote_id:
                    raise UserError("Invalid response from Channex for the creation of property corresponding to company with id %s" % str(property.id))
                property_mapping.write({'x_remote_id': remote_id})
            except Exception as e:
                sync_type = env.context.get('sync_type', 'Live')
                env.ref('booking_channex.util_log_message').with_context(func='POST', path='properties', message=f"{sync_type} sync: Failed to send property with ID {property.id}; error is :\n{str(e)}").run()

property_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[('x_model_type', '=', 'property'),('x_local_id', 'in', records.ids)], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
for property in records:
    if remote_id := property_mappings_dict.get(property.id):
        try:
            env.ref('booking_channex.requests_to_channex').with_context(method="PUT", endpoint="properties/%s" % remote_id, payload={
                "property": {
                    "title": property.name,
                    "currency": property.currency_id.name,
                    "email": property.email or '',
                    "phone": property.phone or '',
                    "property_type": "hotel",  # TODO: Should be adapted based on the industry we use
                    "zip_code": property.zip or '',
                    "country": property.country_id.code or '',
                    "state": property.state_id.name or '',
                    "city": property.city or '',
                    "address": property.street or '',
                    "timezone": property.tz or '',
                    "website": property.website or '',
                }
            }).run()
        except Exception as e:
            sync_type = env.context.get('sync_type', 'Live')
            env.ref('booking_channex.util_log_message').with_context(func='PUT', path='properties', message=f"{sync_type} sync: Failed to update property with ID {property.id}; error is :\n{str(e)}").run()

if env['ir.config_parameter'].get_bool('booking_channex.synced_with_channex'):
    room_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[('x_model_type', '=', 'room_type'),('x_local_id', 'in', records.ids)], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
    for room in records:
        if property_mapping := env['x_channex_mapping'].search([('x_model_type', '=', 'property'), ('x_local_id', '=', room.company_id.id or env.company.id), ('x_remote_id', '!=', False)], limit=1):
            mapped_product = env["x_channex_mapping"].search([("x_model_type", "=", "room_type"), ("x_local_id", "=", room.id)], limit=1)
            guests_attribute_value = room.product_template_attribute_value_ids.filtered(lambda a: a.product_attribute_value_id.attribute_id.x_accommodation_characteristic in ['guest']).mapped('product_attribute_value_id')
            room_can_be_on_channex = (len(guests_attribute_value) == 1 and room.x_is_a_room_offer and room.product_tmpl_id.x_has_rates_attribute and room.active)
            if room_can_be_on_channex and mapped_product: #Update
                if remote_id := room_mappings_dict.get(room.id):
                    try:
                        res = env.ref('booking_channex.requests_to_channex').with_context(method="PUT", endpoint="room_types/%s" % remote_id, payload={
                            "room_type": {
                                "title": room.display_name,
                                "count_of_rooms": room.x_resources_amount or 1,
                                "occ_adults": guests_attribute_value.x_adults, "occ_children": guests_attribute_value.x_children, "occ_infants": guests_attribute_value.x_infants,
                                "default_occupancy": (guests_attribute_value.x_adults + guests_attribute_value.x_children + guests_attribute_value.x_infants) or 1
                            }
                        }).run()
                        if res.json.get('errors', {}).get('code', "") == "resource_not_found":
                            action = {
                                'type': 'ir.actions.client',
                                'tag': 'display_notification',
                                'params': {'message': 'The product could not be updated on channex, as it cannot be found.', 'type': 'warning', 'sticky': False}
                            }
                    except Exception as e:
                        sync_type = env.context.get('sync_type', 'Live')
                        env.ref('booking_channex.util_log_message').with_context(func='PUT', path='room_types', message=f"{sync_type} sync: Failed to update room with ID {room.id}; error is :\n{str(e)}").run()
            elif room_can_be_on_channex and not mapped_product: #Create
                room_mapping = env.ref('booking_channex.get_or_create_mapping').with_context(model_type="room_type", local_id=room.id).run()
                try:
                    data = env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint="room_types", payload={
                        "room_type": {
                            "property_id": property_mapping.x_remote_id,
                            "title": room.display_name,
                            "count_of_rooms": room.x_resources_amount or 1,
                            "occ_adults": guests_attribute_value.x_adults, "occ_children": guests_attribute_value.x_children, "occ_infants": guests_attribute_value.x_infants,
                            "default_occupancy": (guests_attribute_value.x_adults + guests_attribute_value.x_children + guests_attribute_value.x_infants) or 1
                        }
                    }).run()
                    remote_id = data.json.get('data', {}).get('attributes', {}).get('id')
                    if not remote_id: raise UserError("Invalid response from Channex for the creation of room corresponding to product variant with id %s" % str(room.id))
                    room_mapping.write({'x_remote_id': remote_id})
                except Exception as e:
                    sync_type = env.context.get('sync_type', 'Live')
                    env.ref('booking_channex.util_log_message').with_context(func='POST', path='room_types', message=f"{sync_type} sync: Failed to send room with ID {room.id}; error is :\n{str(e)}").run()
            elif not room_can_be_on_channex and mapped_product: #Delete
                env.ref('booking_channex.delete_room_on_channex').with_context(active_ids=[room.id], active_model="product.product").run()

if env['ir.config_parameter'].get_bool('booking_channex.synced_with_channex'):
