room_type_mappings_dict = dict(env['x_channex_mapping']._read_group(domain=[ ('x_model_type', '=', 'room_type')], groupby=['x_local_id'], aggregates=['x_remote_id:max']))
for record in records:
    room_type_remote_id = room_type_mappings_dict.get(record.id)
    if not room_type_remote_id:
        continue
    availability_records = env['x_availability'].search(
        [('x_stay_offer_id', '=', record.product_tmpl_id.id)],
        order='x_date'
    )
    payload_values.extend(construct_availability_payload(property_remote_id, room_type_remote_id, availability_records, record.product_tmpl_id.x_ota_buffer))
action = payload_values

def create_on_channex(endpoint, payload, mapping, error_msg):
    try:
        data = env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint=endpoint, payload=payload).run()
        remote_id = data.json.get('data', {}).get('attributes', {}).get('id')
        if not remote_id: raise UserError(f"{error_msg}: Invalid response from Channex")
        mapping.write({'x_remote_id': remote_id})
    except Exception as e: env.ref('booking_channex.util_log_message').with_context(func='POST', path=endpoint, message=f"Manual Sync: Failed to send {mapping.x_model_type} with ID {mapping.x_local_id}; error is :\n{str(e)}").run()

