def log_sync_message(func, path, mes): env.ref('booking_channex.util_log_message').with_context(message=mes, path=path, func=func).run()
def general_check_records_synced(odoo_model, record_type, channex_endpoint, valid_records, fields_to_compare):
    to_add, to_update = [], []
    try:
        all_channex_records = env.ref('booking_channex.util_get_all_from_channex').with_context(endpoint=channex_endpoint).run() or []
    except Exception as e:
        log_sync_message('GET', channex_endpoint, f"Daily sync: Failed to get channex data ; error is :\n{str(e)}")
        return [], [], []
    channex_record_by_id = {rec.get('id'): rec for rec in all_channex_records}
    channex_records_mapping, odoo_records_mapping = {}, {} # Will contain {channex_id: odoo_id} and {odoo_id: channex_id}
    for mapping_record in env['x_channex_mapping'].search([('x_model_type', '=', record_type)]):
        odoo_record = env[odoo_model].browse(mapping_record.x_local_id)
        channex_records_mapping[mapping_record.x_remote_id] = odoo_record
        odoo_records_mapping[odoo_record] = mapping_record.x_remote_id

    for record in valid_records:
        if record_remote_id := odoo_records_mapping.get(record):
            if not channex_record_by_id.get(record_remote_id):
                to_add.append(record.id)
        else:
            to_add.append(record.id)

    for odoo_record in odoo_records_mapping.keys():
        if channex_dict := channex_record_by_id.get(odoo_records_mapping[odoo_record], {}).get('attributes'):
            for key, value in fields_to_compare.items():
                if odoo_record[key] != channex_dict.get(value):
                    to_update.append(odoo_record.id)
                    break
    return to_add, to_update

