        property_rooms = rooms.filtered(lambda r: r.company_id == property_id) if env['res.company'].search_count([]) > 1 else rooms
        if property_rooms:
            availabilty_payload.extend(env.ref('booking_channex.prepare_availability_payload').with_context(active_ids=property_rooms.ids, active_id=property_rooms.ids[0], active_model="product.product", property_remote_id=property_remote_id).run())
        rate_plans = env['x_rate_plan'].search([('x_variant_id', 'in', property_rooms.ids)])
        if rate_plans:
            restriction_payload.extend(env.ref('booking_channex.prepare_rate_payload').with_context(active_ids=rate_plans.ids, active_id=rate_plans.ids[0], active_model="x_rate_plan", property_remote_id=property_remote_id, date_list=date_list).run())
try: env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint="availability", payload={'values': availabilty_payload}).run()
except Exception as e: log_sync_message('POST', 'availability', f"Daily sync: Failed to send availabilities ; error is :\n{str(e)}")
try: env.ref('booking_channex.requests_to_channex').with_context(method="POST", endpoint="restrictions", payload={'values': restriction_payload}).run()
except Exception as e: log_sync_message('POST', 'restrictions', f"Daily sync: Failed to send rates to rate plans; error is :\n{str(e)}")

log_sync_message('/', '/', "Daily sync: The daily synchronization finished running")

env['ir.cron']._commit_progress(remaining=0)

rate_plans_to_create = []
pricelists = env.context.get('pricelists', False) or env['product.pricelist'].search([('x_published_on_channex', '=', True), ('active', '!=', False)])
products = env.context.get('products', False) or env['product.product'].search([('x_is_a_room_offer', '!=', False), ('active', '!=', False)])
existing_rate_plans = dict(env['x_rate_plan']._read_group(domain=[('x_variant_id', 'in', products.ids), ('x_pricelist_id', 'in', pricelists.ids)], groupby=['x_variant_id'], aggregates=['x_rate_plan_value_id:recordset']))
for pricelist in pricelists:
    for product in products:
        guests_attribute_value = product.product_template_attribute_value_ids.filtered(lambda a: a.product_attribute_value_id.attribute_id.x_accommodation_characteristic in ['guest']).mapped('product_attribute_value_id')
        if len(guests_attribute_value) != 1:
            product.x_rate_plans_ids.unlink()
            continue
        rates_already_applied = existing_rate_plans.get(product, False) or env['product.attribute.value']
        rate_plan_attribute_lines = product.attribute_line_ids.filtered(lambda line: line.attribute_id.x_accommodation_characteristic in ['rate_plan'])
        x_rate_plan_falsy_rate = product.x_rate_plans_ids.filtered(lambda r: not r.x_rate_plan_value_id and r.x_pricelist_id.id == pricelist.id)
        rates_to_add = []
        if rate_plan_attribute_lines:
            rates_to_add = (rate_plan_attribute_lines.value_ids-rates_already_applied).ids
            x_rate_plan_falsy_rate.unlink()
            rates_to_remove = rates_already_applied-rate_plan_attribute_lines.value_ids
        else:
            if not x_rate_plan_falsy_rate:
                rates_to_add = [False]
            rates_to_remove = rates_already_applied
        for value in rates_to_add:
            rate_plans_to_create.append({
                'x_variant_id': product.id,
                'x_rate_plan_value_id': value,
                'x_pricelist_id': pricelist.id,
            })
        if rates_to_remove:
            product.x_rate_plans_ids.filtered(lambda r: r.x_rate_plan_value_id.id in rates_to_remove.ids).unlink()
env['x_rate_plan'].create(rate_plans_to_create)

 # Need to check if active, because other action in automation does not want it as a domain and otherwise it could be create rate plan without room on channex
if active_products := records.filtered(lambda p: p.active):
    records.env.ref('booking_channex.server_action_create_remove_rate_plans').with_context(products=active_products).run()
